3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneConflictException;
8	
9	/**
10	 * Runs after {@link ValidateOwnerFields} (whose normalized telephone this step reads via {@code @Val})
11	 * and before {@link BuildOwner}: rejects the request with 409 when any existing owner already uses the
12	 * same telephone. The request telephone is already in E.164 form (set by {@link ValidateOwnerFields});
13	 * every stored owner's telephone is normalized to E.164 the same way before comparison, so
14	 * differently-formatted duplicates are still caught.
15	 */
16	public class CheckOwnerTelephoneUnique {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws OwnerTelephoneConflictException {
20	        String telephone = E164Telephone.normalize(request.getTelephone());
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (telephone.equals(E164Telephone.normalize(existing.getTelephone()))) {
23	                throw new OwnerTelephoneConflictException(
24	                        "An owner with telephone " + telephone + " already exists");
25	            }
26	        }
27	    }
28	}
