3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.OwnerEmailConflictException;
10	
11	/**
12	 * Runs after {@link ValidateOwnerFields} (whose lower-cased email this step reads via {@code @Val})
13	 * and before {@link BuildOwner}: rejects the request with 409 when any existing owner already uses the
14	 * same email. Email is optional, so a request without one is left to pass. Comparison is on the
15	 * lower-cased value, so differently-cased duplicates are still caught.
16	 */
17	public class CheckOwnerEmailUnique {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws OwnerEmailConflictException {
21	        String email = normalize(request.getEmail());
22	        if (email == null) {
23	            return;
24	        }
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (email.equals(normalize(existing.getEmail()))) {
27	                throw new OwnerEmailConflictException(
28	                        "An owner with email " + email + " already exists");
29	            }
30	        }
31	    }
32	
33	    private static String normalize(String email) {
34	        if (email == null) {
35	            return null;
36	        }
37	        String trimmed = email.trim();
38	        return trimmed.isEmpty() ? null : trimmed.toLowerCase(Locale.ROOT);
39	    }
40	}
