1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerHouseholdConflictException;
8	
9	/**
10	 * Runs after {@link CheckOwnerTelephoneUnique} and before {@link BuildOwner}: rejects the request
11	 * with 409 when another owner already has the same last name at the same address. Both the last
12	 * name and the address are compared case-insensitively with runs of whitespace collapsed to a
13	 * single space, so differently-cased or -spaced duplicates are still caught. A request may opt out
14	 * of the check by setting {@code sharesHousehold: true} (two owners sharing one household).
15	 */
16	public class CheckOwnerHouseholdUnique {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws OwnerHouseholdConflictException {
20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        String lastName = normalize(request.getLastName());
24	        String address = AddressNormalizer.normalize(request.getAddress());
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (lastName.equals(normalize(existing.getLastName()))
27	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
28	                throw new OwnerHouseholdConflictException("An owner with last name "
29	                        + request.getLastName() + " already lives at " + request.getAddress());
30	            }
31	        }
32	    }
33	
34	    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
35	    private static String normalize(String value) {
36	        if (value == null) {
37	            return "";
38	        }
39	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
40	    }
41	}
