1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Normalizes a telephone number to E.164 form:
5	 * <ul>
6	 *   <li>separators (spaces, dashes, brackets and the like) are stripped;</li>
7	 *   <li>a leading {@code '+'} and country code are kept when present;</li>
8	 *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
9	 *       is dropped from the national digits;</li>
10	 *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
11	 *   <li>the national-number length must match the country code: {@code '+61'} requires 9
12	 *       national digits and {@code '+1'} requires 10.</li>
13	 * </ul>
14	 * So {@code "0412 345 678"} becomes {@code "+61412345678"}. Returns {@code null} when the
15	 * input cannot form a valid E.164 number.
16	 */
17	final class E164Telephone {
18	
19	    private static final int MIN_DIGITS = 8;
20	    private static final int MAX_DIGITS = 15;
21	
22	    /** National-number length required for country code {@code '+61'}. */
23	    private static final int AU_NATIONAL_DIGITS = 9;
24	
25	    /** National-number length required for country code {@code '+1'}. */
26	    private static final int NANP_NATIONAL_DIGITS = 10;
27	
28	    private E164Telephone() {
29	    }
30	
31	    static String normalize(String raw) {
32	        if (raw == null) {
33	            return null;
34	        }
35	        String trimmed = raw.trim();
36	        boolean explicitCountryCode = trimmed.startsWith("+");
37	        String digits = trimmed.replaceAll("\\D", "");
38	        if (!explicitCountryCode) {
39	            if (digits.startsWith("0")) {
40	                digits = digits.substring(1);
41	            }
42	            digits = "61" + digits;
43	        }
44	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
45	            return null;
46	        }
47	        // National-number length must match the country code.
48	        if (digits.startsWith("61")) {
49	            if (digits.length() - 2 != AU_NATIONAL_DIGITS) {
50	                return null;
51	            }
52	        }
53	        else if (digits.startsWith("1")) {
54	            if (digits.length() - 1 != NANP_NATIONAL_DIGITS) {
55	                return null;
56	            }
57	        }
58	        return "+" + digits;
59	    }
60	}
