1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsInvalidException;
10	import org.springframework.web.bind.annotation.RequestBody;
11	
12	/**
13	 * First step of {@code POST /api/owners}: rejects a request that is missing or blank in any of
14	 * firstName, lastName, address, city or telephone. Throwing lists every offending field, so the
15	 * client sees them all at once. The address is normalized (trim/collapse whitespace, upper-case, and
16	 * expand ST/RD/AVE) and written back, and is treated as absent when blank after normalization. It
17	 * also normalizes the telephone into E.164 form (keeping a leading
18	 * '+' and country code when present, otherwise assuming '+61' and dropping a single leading '0'),
19	 * rejecting with 400 when it cannot form a valid E.164 number; the normalized value is
20	 * written back onto the body. When an optional {@code email} is present it must be a syntactically
21	 * valid address (else 400); it is lower-cased and written back. On success it publishes the body for
22	 * {@link BuildOwner} to map.
23	 */
24	public class ValidateOwnerFields {
25	
26	    /** Syntactic email check: a non-empty local part, an {@code @}, then a dotted domain. */
27	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
28	
29	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
30	            throws OwnerFieldsInvalidException {
31	        List<String> errors = new ArrayList<>();
32	        checkPresent("firstName", request.getFirstName(), errors);
33	        checkPresent("lastName", request.getLastName(), errors);
34	        // Reject an address that is blank once normalized (trim/collapse/upper-case), so
35	        // whitespace-only input fails the required-field check like any other missing field.
36	        String address = AddressNormalizer.normalize(request.getAddress());
37	        if (address.isEmpty()) {
38	            errors.add("address");
39	        }
40	        checkPresent("city", request.getCity(), errors);
41	        checkPresent("telephone", request.getTelephone(), errors);
42	        if (!errors.isEmpty()) {
43	            throw new OwnerFieldsInvalidException(errors);
44	        }
45	        // Store and return the normalized address; later steps read it back via @Val.
46	        request.setAddress(address);
47	        String telephone = E164Telephone.normalize(request.getTelephone());
48	        if (telephone == null) {
49	            throw new OwnerFieldsInvalidException(List.of("telephone"));
50	        }
51	        request.setTelephone(telephone);
52	        String email = request.getEmail();
53	        if (email != null && !email.trim().isEmpty()) {
54	            email = email.trim();
55	            if (!EMAIL.matcher(email).matches()) {
56	                throw new OwnerFieldsInvalidException(List.of("email"));
57	            }
58	            request.setEmail(email.toLowerCase());
59	        }
60	        validated.set(request);
61	    }
62	
63	    private static void checkPresent(String field, String value, List<String> errors) {
64	        if (value == null || value.trim().isEmpty()) {
65	            errors.add(field);
66	        }
67	    }
68	}
