1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	
12	/**
13	 * Runs after {@link BuildOwner} when the request set {@code sharesHousehold: true}: the new owner is
14	 * joining an existing household (another owner with the same last name at the same address, already
15	 * permitted by {@link CheckOwnerHouseholdUnique}). Assigns a stable, shared {@code householdId} to the
16	 * new owner and back-fills it onto the existing household member(s), so every owner in the household
17	 * reports the same identifier.
18	 *
19	 * <p>The identifier is derived deterministically from the normalized last name and address (compared
20	 * the same way as {@link CheckOwnerHouseholdUnique}), so it is stable across creations and identical
21	 * for everyone in one household regardless of the order they were added.
22	 */
23	public class AssignHouseholdId {
24	
25	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
26	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
27	            return;
28	        }
29	        String lastName = normalize(owner.getLastName());
30	        String address = AddressNormalizer.normalize(owner.getAddress());
31	        String householdId = deriveHouseholdId(lastName, address);
32	        owner.setHouseholdId(householdId);
33	        // Back-fill the shared id onto the existing household member(s) so both sides match.
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (lastName.equals(normalize(existing.getLastName()))
36	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))
37	                    && !householdId.equals(existing.getHouseholdId())) {
38	                existing.setHouseholdId(householdId);
39	                ownerRepository.save(existing);
40	            }
41	        }
42	    }
43	
44	    /** Stable 12-character upper-case hex identifier derived from the household's name and address. */
45	    private static String deriveHouseholdId(String lastName, String address) {
46	        try {
47	            byte[] digest = MessageDigest.getInstance("SHA-256")
48	                    .digest((lastName + "\n" + address).getBytes(StandardCharsets.UTF_8));
49	            StringBuilder sb = new StringBuilder();
