2	
3	/**
4	 * Normalizes a street address into a single canonical form used both for storage and for every
5	 * address comparison (household duplicate detection and the shared household id):
6	 * <ul>
7	 *   <li>leading and trailing whitespace is trimmed and internal whitespace runs are collapsed to a
8	 *       single space;</li>
9	 *   <li>the text is upper-cased;</li>
10	 *   <li>common trailing-type abbreviations are expanded as whole words: {@code ST -> STREET},
11	 *       {@code RD -> ROAD}, {@code AVE -> AVENUE}.</li>
12	 * </ul>
13	 * So {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}. Returns {@code ""} for a
14	 * {@code null} or whitespace-only input, so callers can treat a blank-after-normalization address
15	 * as absent.
16	 */
17	final class AddressNormalizer {
18	
19	    private AddressNormalizer() {
20	    }
21	
22	    static String normalize(String raw) {
23	        if (raw == null) {
24	            return "";
25	        }
26	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase();
27	        if (collapsed.isEmpty()) {
28	            return "";
29	        }
30	        String[] tokens = collapsed.split(" ");
31	        StringBuilder sb = new StringBuilder(collapsed.length());
32	        for (int i = 0; i < tokens.length; i++) {
33	            if (i > 0) {
34	                sb.append(' ');
35	            }
36	            sb.append(expand(tokens[i]));
37	        }
38	        return sb.toString();
39	    }
40	
41	    private static String expand(String token) {
42	        switch (token) {
43	            case "ST":
44	                return "STREET";
45	            case "RD":
46	                return "ROAD";
47	            case "AVE":
48	                return "AVENUE";
49	            default:
50	                return token;
51	        }
52	    }
53	}
